# cook your dish here
import sys

MOD = 998244353

input = sys.stdin.readline

T= int(input())

for _ in range(T):
    n = int(input())
    
    pos =[[] for _ in range(n+1)]
    
    arr = list(map(int,input().split()))
    
    for i in range(1,n+1):
        x = arr[i-1]
        pos[x].append(i)
     
    impossible = False
    
    for x in range(1,n+1):
        if len(pos[x]) > 9:
            impossible = True
            break
        
    if impossible:
        print(0)
        continue
    
    dp = [0] * (n+1)
    ndp = [0] * (n+1)
    dp[0] = 1 
    
    def smallLE(y,s,q):
        if q <= 0:
            return 0
        res = min(q,s)
        
        R = n - y + 2 + s
        
        if q >= R:
            res += q - R + 1 
            
        return res 
    
    for y in range(1, n):
        ndp = [0] * (n+1)
        for s in range(y):
            if dp[s] == 0:
                continue
            
            for left in range(2):
                if left: py = s + 1 
                else: py = n-y+1+s
                
                ok = True
                
                for i in pos[y]:
                    
                    prefix = False
                    suffix = False
                    
                    if py <= i:
                        smaller = smallLE(y,s,i)
                        prefix = (smaller == (i -1)//2)
                        
                    if py >= i:
                        smallerbefore = smallLE(y,s,i-1)
                        smallersuffix = y - 1 - smallerbefore
                        
                        suffix = (smallersuffix == (n-i)//2)
                        
                    if not prefix and not suffix:
                        ok = False
                        break
                    
                if ok :
                    ns = s + left
                    ndp[ns] += dp[s]
                    
                    if ndp[ns] >= MOD:
                        ndp[ns] -= MOD
                
        dp = ndp
    
    ans = 0
    
    for s in range(n):
        if dp[s] == 0:
            continue
        
        ok = True
        
        for i in pos[n]:
            
            if not ((i == 1 and s == 0) or ( i == n and s == n-1)):
                ok = False
                break
        
        if ok:
            ans += dp[s]
            
            if ans >= MOD:
                ans -= MOD
                
    print(ans)
